// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * Pluggable resolvers for the DSL's non-deterministic branches.
 *
 * - PromptEvaluator: resolves `prompt` fields (AI). The default offline
 *   evaluator resolves nothing — callers record the prompt in
 *   `instance.pending_prompts` and fall back to deterministic behavior.
 * - Directory: resolves assignee/recipient queries ({ department, role, ... })
 *   to user ids. The default is an in-memory directory seeded via the API.
 */
import type { DirectoryQuery } from '../../../dsl/types.ts';
import { matches } from './mongo.ts';
import { DEFAULT_ORGANIZATION_ID } from './identity.ts';

export interface PromptEvaluator {
  evaluate(prompt: string, context: Record<string, unknown>): Promise<unknown | undefined>;
}

/** Offline default: never resolves, keeping the engine fully deterministic. */
export const offlineEvaluator: PromptEvaluator = {
  async evaluate() {
    return undefined;
  },
};

export interface DirectoryUser {
  id: string;
  organization_id?: string;
  email?: string;
  department?: string;
  /** Every department the person belongs to; `department` stays for callers
   * that know only one. */
  departments?: string[];
  role?: string;
  /**
   * This person's reporting managers — their rows of the platform's
   * `ReportingMatrix`, denormalized onto the person so an assignee query can
   * filter on them the same way it filters on `employment_status_active`.
   * Seeding these also registers them with RBAC, so reportee-scoped permission
   * and assignment agree rather than drifting apart.
   */
  reporting_managers?: string[];
  [key: string]: unknown;
}

export class Directory {
  private users: DirectoryUser[] = [];

  seed(users: DirectoryUser[], organizationId = DEFAULT_ORGANIZATION_ID): void {
    const normalized = users.map((user) => ({ ...user, organization_id: organizationId }));
    this.users = [
      ...this.users.filter((user) => (user.organization_id ?? DEFAULT_ORGANIZATION_ID) !== organizationId),
      ...normalized,
    ];
  }

  all(organizationId?: string): DirectoryUser[] {
    return this.users.filter(
      (user) => !organizationId || (user.organization_id ?? DEFAULT_ORGANIZATION_ID) === organizationId,
    );
  }

  get(id: string, organizationId = DEFAULT_ORGANIZATION_ID): DirectoryUser | undefined {
    return this.users.find(
      (user) => user.id === id &&
        (user.organization_id ?? DEFAULT_ORGANIZATION_ID) === organizationId,
    );
  }

  /** Upsert one person — how the platform reports a joiner, mover or leaver. */
  upsert(user: DirectoryUser, organizationId = DEFAULT_ORGANIZATION_ID): { created: boolean } {
    const normalized = { ...user, organization_id: organizationId };
    const i = this.users.findIndex(
      (existing) => existing.id === user.id &&
        (existing.organization_id ?? DEFAULT_ORGANIZATION_ID) === organizationId,
    );
    if (i < 0) {
      this.users.push(normalized);
      return { created: true };
    }
    this.users[i] = { ...this.users[i], ...normalized };
    return { created: false };
  }

  /** ai_context is advisory (prompt material), not a filter — strip it before matching. */
  query(
    q: DirectoryQuery | Record<string, unknown>,
    limit = Infinity,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): DirectoryUser[] {
    const { ai_context: _ignored, ...filter } = q as Record<string, unknown>;
    const clean = Object.fromEntries(
      Object.entries(filter).filter(([, v]) => v !== '' && v !== undefined && v !== null),
    );
    return this.users
      .filter((user) => (user.organization_id ?? DEFAULT_ORGANIZATION_ID) === organizationId)
      .filter((user) => matches(user, clean))
      .slice(0, limit);
  }
}
